"""Owner-only, explicit-click 2-factor JRDB pilot (no betting)."""
HTML = "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#09172b\"><title>KEIBA NINE｜1レース自動試算</title><link rel=\"stylesheet\" href=\"/owner-auto-trial.css\"></head><body><main><a href=\"/\">← 本人用ホーム</a><h1>1レースの自動試算</h1><p class=\"warning\">JRDBの非公開APIに接続できた場合だけ、調教・近走の2項目から「研究用の暫定比較順」を自動計算します。**実戦予想・AI総合評価・3連単の買い目ではありません**。JRA公式出走表や取消の照合も未実施です。</p><section><h2>対象レース</h2><label for=\"trialDate\">開催日</label><input id=\"trialDate\" type=\"date\"><label for=\"trialTrack\">競馬場</label><select id=\"trialTrack\"><option value=\"\">競馬場を選択</option><option>札幌</option><option>函館</option><option>福島</option><option>新潟</option><option>東京</option><option>中山</option><option>中京</option><option>京都</option><option>阪神</option><option>小倉</option></select><label for=\"trialRace\">レース</label><select id=\"trialRace\"></select><p id=\"trialConnect\" class=\"muted\" role=\"status\">本人用JRDB接続設定を確認しています。</p><button id=\"trialRun\" disabled type=\"button\">この1Rの調教・近走を自動試算</button><p id=\"trialStatus\" class=\"muted\" role=\"status\">未実行。結果はこの画面だけで表示し、保存・購入しません。</p></section><section><h2>2項目の暫定比較順</h2><p class=\"muted\">各馬のS/A/B/Cは既存の未検証な独自仮説。総合S/A/B/Cや勝率に変換しません。同点は同順位、資料不足馬は順位を付けません。人気やオッズは使用しません。</p><div id=\"trialSummary\" role=\"status\"></div><div id=\"trialRows\" aria-label=\"本人専用の2項目暫定試算\"></div><p class=\"warning\">これを根拠に馬券を作成する機能はありません。今後、血統・展開・馬場・コース適性などの評価と公式照合ができてから、本番の自動予想へ進みます。</p></section><a href=\"/owner-races\">36R一覧へ戻る</a></main><script src=\"/owner-auto-trial.js\" defer></script></body></html>"
CSS = "*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#09172b;color:#eef4fb;font:16px/1.65 system-ui,sans-serif}main{max-width:690px;margin:auto;padding:18px 16px 55px}h1{font-size:24px;color:#f2d387}section{background:#142940;border:1px solid #45637f;border-radius:14px;padding:16px;margin:13px 0}h2{font-size:18px;margin:0 0 10px}p{overflow-wrap:anywhere}.muted{color:#c7d6e6;font-size:14px}.warning{background:#2c2926;border:1px solid #a88f57;border-radius:10px;padding:11px;font-size:14px;color:#ffe9b9}label{display:block;font-weight:700;margin-top:11px}button,input,select{width:100%;font:inherit;padding:12px;min-height:44px;background:#0b1d30;color:white;border:1px solid #819bb1;border-radius:10px;margin-top:5px}button{background:#e9c675;color:#172c3d;border:0;font-weight:800;margin-top:14px}button:disabled{opacity:.45}.trial-horse{background:#0a223a;border:1px solid #527390;border-radius:10px;margin:8px 0;padding:10px 13px}.trial-horse strong{color:#f2d38c}.trial-horse p{margin:4px 0;font-size:14px}.not-ready{color:#ffd0b9}a{color:#e7d38b}"
JS = "(()=>{'use strict';\nconst $=id=>document.getElementById(id);\nconst tracks=['札幌','函館','福島','新潟','東京','中山','中京','京都','阪神','小倉'];\nlet connected=false,seq=0;\nfunction validDay(date){\n if(!/^20\\d{2}-\\d{2}-\\d{2}$/.test(date))return false;\n const t=new Date(date+'T12:00:00Z');\n return Number.isFinite(t.valueOf())&&t.toISOString().slice(0,10)===date;\n}\nfunction selected(){\n const date=$('trialDate').value,track=$('trialTrack').value,race=$('trialRace').value;\n if(!validDay(date)||!tracks.includes(track)||!/^(?:[1-9]|1[0-2])$/.test(race))\n  return null;\n return {date:date.replaceAll('-',''),track,race};\n}\nfunction update(){\n $('trialRun').disabled=!connected||!selected();\n}\nfunction clear(){\n seq++;\n $('trialRows').replaceChildren();\n $('trialSummary').textContent='';\n $('trialStatus').textContent='レースの選択が変わりました。試算を実行してください。';\n update();\n}\nasync function request(url){\n const r=await fetch(url,{credentials:'same-origin',\n  headers:{'X-Keiba-Request':'private','Accept':'application/json'},\n  cache:'no-store'});\n const data=await r.json();\n if(!r.ok)throw Error(data.error||'接続できません');\n return data;\n}\nfunction validateReply(d,selection){\n if(!d||d.version!=='owner-single-race-two-factor-trial-1'||\n  d.date!==selection.date||d.track!==selection.track||\n  d.race!==Number(selection.race)||d.predictionReady!==false||\n  d.bettingReady!==false||d.overallRankReady!==false||\n  d.autoTicketReady!==false||d.officialJraVerified!==false||\n  d.researchOnly!==true||d.unverifiedFactors!==8||\n  !Array.isArray(d.runners)||d.runners.length<1||d.runners.length>18||\n  d.runners.length!==d.runnersObserved||\n  !Number.isInteger(d.twoFactorComparable)||\n  d.twoFactorComparable+d.ungraded!==d.runners.length)\n  throw Error('安全な試算結果として検証できません。');\n const seen=new Set(),allowed=['S','A','B','C','未評価'];\n let previous=-Infinity,complete=0;\n for(const row of d.runners){\n  if(!Number.isInteger(row.horseNumber)||row.horseNumber<1||row.horseNumber>18||\n    seen.has(row.horseNumber)||!allowed.includes(row.trainingGrade)||\n    !allowed.includes(row.recentGrade)||row.provisionalOnly!==true)\n   throw Error('馬番・暫定評価を確認できません。');\n  seen.add(row.horseNumber);\n  const eligible=row.trainingGrade!=='未評価'&&row.recentGrade!=='未評価';\n  if(eligible){\n   complete++;\n   if(!Number.isInteger(row.twoFactorPoints)||\n     row.twoFactorPoints<2||row.twoFactorPoints>8||\n     !Number.isInteger(row.comparisonRank)||row.comparisonRank<1||\n     previous===999)throw Error('暫定順位を確認できません。');\n   if(previous!==-Infinity&&row.twoFactorPoints>previous)throw Error('比較順が不正です。');\n   previous=row.twoFactorPoints;\n  }else{\n   if(row.twoFactorPoints!==null||row.comparisonRank!==null)\n    throw Error('不足項目が順位に混ざっています。');\n   previous=999;\n  }\n }\n if(complete!==d.twoFactorComparable)throw Error('採点件数が一致しません。');\n return true;\n}\n$('trialDate').value=new Date(Date.now()+9*3600000).toISOString().slice(0,10);\nfor(let i=1;i<=12;i++){\n const o=document.createElement('option');o.value=String(i);o.textContent=i+'R';\n $('trialRace').append(o);\n}\n// Receive ONLY race coordinates from the 36R dashboard; no paid data in URLs.\nconst incoming=typeof window!=='undefined'&&window.location&&\n  typeof window.location.hash==='string'?window.location.hash:'';\nif(incoming.startsWith('#select=v1&')&&incoming.length<=160){\n try{\n  const q=new URLSearchParams(incoming.slice(1));\n  if(q.size===4&&['select','date','track','race'].every(k=>q.has(k))&&\n     q.get('select')==='v1'&&validDay(q.get('date'))&&\n     tracks.includes(q.get('track'))&&\n     /^(?:[1-9]|1[0-2])$/.test(q.get('race'))){\n   $('trialDate').value=q.get('date');\n   $('trialTrack').value=q.get('track');\n   $('trialRace').value=q.get('race');\n  }\n }catch(_){/* Untrusted fragment ignored; no API request. */}\n}\n$('trialDate').onchange=clear;$('trialTrack').onchange=clear;$('trialRace').onchange=clear;\n$('trialRun').onclick=async()=>{\n const choice=selected();if(!connected||!choice)return;\n const stamp=++seq;\n $('trialRun').disabled=true;$('trialRows').replaceChildren();$('trialSummary').textContent='';\n $('trialStatus').textContent='この1RのJRDB資料を本人用サーバーで照合しています。';\n try{\n  const q=new URLSearchParams(choice);\n  const result=await request('/api/jrdb/one-race-trial?'+q.toString());\n  if(stamp!==seq||!selected()||selected().date!==choice.date||\n     selected().track!==choice.track||selected().race!==choice.race)return;\n  validateReply(result,choice);\n  $('trialSummary').textContent=choice.track+Number(choice.race)+'R：'+\n   result.runnersObserved+'頭のうち2項目比較可能 '+result.twoFactorComparable+'頭／未評価 '+\n   result.ungraded+'頭。総合ランク・買い目は未作成。';\n  for(const h of result.runners){\n   const card=document.createElement('div');card.className='trial-horse';\n   const head=document.createElement('strong');\n   head.textContent=h.comparisonRank===null?\n     h.horseNumber+'番｜順位未評価':\n     '暫定'+h.comparisonRank+'位｜'+h.horseNumber+'番';\n   const p=document.createElement('p');\n   p.textContent='調教 '+h.trainingGrade+'／近走 '+h.recentGrade+\n    (h.twoFactorPoints===null?'／2項目の比較不可':'／研究用2項目合計 '+h.twoFactorPoints);\n   card.append(head,p);$('trialRows').append(card);\n  }\n  $('trialStatus').textContent=result.warning;\n }catch(e){\n  if(stamp===seq)$('trialStatus').textContent='試算できません：'+\n   (e instanceof Error?e.message:'データを確認してください。');\n }finally{if(stamp===seq)update();}\n};\nrequest('/api/status').then(s=>{\n connected=s.jrdbConfigured===true;\n $('trialConnect').textContent=connected?\n  '本人用JRDB認証情報の設定あり。接続や予想精度を保証するものではありません。':\n  'JRDB β版の専用API認証情報が未設定です。発行とRenderの非公開設定が必要です。';\n update();\n}).catch(()=>{\n connected=false;update();\n $('trialConnect').textContent='接続設定を確認できません。ログインと通信を確認してください。';\n});\n})();"
